"""Owner-matched ATD projects, with verified public reviews and area-only locations."""
from html import escape
from pathlib import Path
import json
PROJECT_PAGES={
 '/projects/stamford-hill-exterior/':{'title':'Decorating & Refurbishment Project in Stamford Hill N16','description':'Real ATD project photos from Stamford Hill N16: entrance decorating, glazed doors, timber floors and front-step tiles, with John Burgess’s Google review.','label':'Stamford Hill project','image_slug':'project-story-245'},
 '/projects/crouch-end-redecoration/':{'title':'Redecoration & Terrace Project in Crouch End N8','description':'ATD project in Crouch End N8: coral painted details and terrace decking stages, with real photographs and Julian Smilg’s Google review.','label':'Crouch End project','image_slug':'project-story-065'},
 '/projects/leyton-bathroom/':{'title':'Bathroom Refurbishment Project in Leyton E10','description':'A real ATD bathroom refurbishment in Leyton E10, from strip-out to red floor tiles and fittings, with Menna Cominetti’s Google review.','label':'Leyton bathroom project','image_slug':'wc-refurbishment-progress-photo'}
}
CASES={
 '/projects/stamford-hill-exterior/':dict(area='Stamford Hill, N16',headline='One home.<br><em>Care across the details.</em>',intro='Entrance decorating, exterior glazed doors, timber floor finishing and patterned front-step tiles from the same property. These photographs show different parts and stages of one ATD project.',ids=['yellow-door','timber-floor','entrance-tiles'],service='full-refurbishments',scope='Exterior decorating, repointing, timber floors and entrance tiling',context='The work at this property also included repointing. John’s Google review describes the exterior painting and brickwork; it does not list every part shown here.',extra=[('glazed-doors-preparation-photo','Exterior glazed doors during preparation')]),
 '/projects/crouch-end-redecoration/':dict(area='Crouch End, N8',headline='Colour inside.<br><em>Terrace details outside.</em>',intro='Coral-painted shelving and chimney-wall details, alongside photographs of the terrace framework and decking. These are two parts of the same Crouch End project.',ids=['coral-room','terrace'],service='full-refurbishments',scope='Interior decorating and terrace decking',context='Julian’s review describes a range of redecoration tasks and the communication during the project. The terrace photographs show the framework and later decking stage.',extra=[]),
 '/projects/leyton-bathroom/':dict(area='Leyton, E10',headline='A compact bathroom.<br><em>The work as it took shape.</em>',intro='The same bathroom through strip-out, floor access, red floor tiling and the later stage with fittings in place. These photographs follow the Leyton refurbishment as it progressed.',ids=['red-bathroom'],service='bathroom-refurbishments',scope='Bathroom refurbishment',context='The photographs document stages of the bathroom work. Menna’s review comments on Landi’s reliability, communication and finish across the project.',extra=[])
}
PROJECT_PAGES['/projects/e17-kitchen/']={'title':'Kitchen Refurbishment Details in E17','description':'Real ATD kitchen project photographs from E17, showing timber worktops, open shelves and the finishing stage, with Kevin Paskins’s Google review.','label':'E17 kitchen project','image_slug':'kitchen'}
CASES['/projects/e17-kitchen/']=dict(area='E17',headline='A bright kitchen.<br><em>Warm timber details.</em>',intro='Timber worktops and open shelving alongside white cabinetry and grey tiles. These photographs show close-up details and the wider kitchen during the finishing stage.',ids=['kitchen'],service='full-refurbishments',scope='Kitchen refurbishment details',context='Kevin’s review describes working with ATD twice, with clear quotations, attention to details and professional work. The photographs here show the kitchen project.',extra=[])
def project_content(route,button):
 case=CASES[route]; stories=json.loads((Path(__file__).parent/'project-stories.json').read_text()); chosen=[next(s for s in stories if s['id']==sid) for sid in case['ids']]; review=chosen[0]['review']
 out='<section class="page-intro wrap"><p class="kicker">A REAL ATD PROJECT · '+escape(case['area'])+'</p><h1>'+case['headline']+'</h1><p class="lead">'+escape(case['intro'])+'</p>'+button('Discuss similar work','/enquiry/booking.html?service='+case['service'])+'</section>'
 out+='<section class="wrap project-start"><div><p class="kicker">PROJECT AT A GLANCE</p><h2>The work behind<br><em>the photographs.</em></h2></div><div><p><strong>Area:</strong> '+escape(case['area'])+'<br><strong>Work:</strong> '+escape(case['scope'])+'</p><p>'+escape(case['context'])+'</p><p>Preparation, protection and equipment remain visible in some views. Captions identify the stages shown.</p></div></section>'
 for story in chosen:
  out+='<section class="section wrap"><h2>'+escape(story['title'])+'</h2><p class="lead">'+escape(story['text'])+'</p><div class="case-photos">'
  for photo in story['photos']:out+=figure(photo['slug'],photo['caption'])
  out+='</div></section>'
 if case['extra']:
  out+='<section class="section wrap"><h2>Exterior glazed doors</h2><div class="case-photos">'+''.join(figure(slug,caption) for slug,caption in case['extra'])+'</div></section>'
 out+='<section class="connect wrap project-review"><p class="kicker">THE CUSTOMER’S GOOGLE REVIEW</p><h2>'+escape(review['name'])+'</h2><p class="stars" aria-label="5 out of 5 stars">★★★★★</p><blockquote>“'+escape(review['excerpt'])+'”</blockquote><a class="text-link" href="'+escape(review['url'])+'" target="_blank" rel="noopener noreferrer">Read the original Google review ↗</a></section>'
 return out+'<section class="section wrap"><p class="kicker">PLANNING YOUR OWN PROJECT?</p><h2>Tell us about your property.</h2><p class="lead">Send photographs, your postcode and the changes you have in mind. Scope, materials, access and timing are assessed for your home and agreed in a written quotation.</p>'+button('Request a quote','/enquiry/booking.html?service='+case['service'])+'<p class="fine"><a href="/gallery/">See more ATD work ↗</a></p></section>'
def figure(slug,caption):
 return '<figure><a href="/assets/'+escape(slug)+'-1200.webp" target="_blank" rel="noopener noreferrer"><img src="/assets/'+escape(slug)+'-1200.webp" alt="'+escape(caption)+'" loading="lazy" decoding="async"></a><figcaption>'+escape(caption)+'</figcaption></figure>'
